import os,subprocess,json,stat
from pathlib import Path
src=Path('/opt/telegram-robot-leads')
dst=Path('/srv/projects/telegram-robot-leads')
dep=Path('/opt/telegram-robot-leads/.venv')
vault=Path('/root/project-secrets/telegram-robot-leads')
data=Path('/var/lib/telegram-robot-leads')
print('===PATH PREFLIGHT===')
for p in [src,dst,dst.parent,dep,vault,data]:
 if p.exists() or p.is_symlink():
  st=p.lstat()
  print('PATH',str(p),'TYPE','SYMLINK' if p.is_symlink() else 'DIR' if p.is_dir() else 'OTHER','UID',st.st_uid,'GID',st.st_gid,'MODE',oct(st.st_mode & 0o777),'DEV',st.st_dev,'INODE',st.st_ino)
 else: print('PATH',str(p),'ABSENT')
print('===TOP LEVEL FILES===')
if not src.is_dir():raise RuntimeError('Robot source directory not available')
for p in sorted(src.iterdir()):
 st=p.lstat()
 print('TOP',p.name,'dir',p.is_dir(),'link',p.is_symlink(),'size',st.st_size)
print('===PRIVATE SESSION METADATA===')
for p in [vault,data]:
 print('COMPONENT',str(p),'PRESENT',p.is_dir())
 if p.is_dir():
  count=0
  for f in p.iterdir():
   if f.is_file() and f.suffix=='.session':count+=1
  print('SESSION_COUNT',str(p),count)
print('===PM2 ACTIVE===')
r=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=15)
if r.returncode:raise RuntimeError('PM2 unavailable')
for a in json.loads(r.stdout):
 if a.get('name') in ('telegram-robot-leads','iptvpn_bot'):
  e=a.get('pm2_env') or {}
  print('BOT',a.get('name'),'STATUS',e.get('status'),'PID',a.get('pid'),'CWD',e.get('pm_cwd'),'SCRIPT',e.get('pm_exec_path'),'INTERPRETER',e.get('exec_interpreter'))
  for k in ['TELEGRAM_OPERATION_STATE','TELEGRAM_EVENT_JOURNAL','TELEGRAM_TZ','TELEGRAM_GROUP_ALLOWLIST','TELEGRAM_PUBLIC_DISCOVERY_ENABLED']:
   if k in e: print('ENV_META',a.get('name'),k,'PRESENT','ABS_PATH' if str(e[k]).startswith('/') else 'RELATIVE')
print('===PATH REFERENCES PROJECT===')
old='/opt/telegram-robot-leads'
needle_extra=['/root/project-secrets/telegram-robot-leads','/var/lib/telegram-robot-leads','/opt/telegram-leads-optin']
banned={'.venv','archive','.git','.telegram-leads-source-7c0ef8a1d9be','.telegram-leads-release-backups','__pycache__','.rea-tests-backup-655a9115-20261030','optin'}
count=0
for cur,dirs,files in os.walk(src):
 depth=len(Path(cur).parts)-len(src.parts)
 if depth>5:dirs.clear()
 dirs[:]=[x for x in dirs if x not in banned and not x.startswith('.telegram-leads-source')]
 for name in files:
  p=Path(cur)/name
  try:
   if p.is_symlink() or p.stat().st_size>200000:continue
   if p.suffix not in ('.py','.sh','.js','.json','.md','.txt','.yml','.yaml','.service','.timer','.toml','.ini') and p.name not in ('Makefile','Dockerfile'):continue
   text=p.read_text(errors='replace')
   hits=[]
   for needle in [old]+needle_extra:
    nc=text.count(needle)
    if nc:hits.append((needle,nc))
   if hits:
    print('SRCREF',str(p.relative_to(src)),str(hits))
    count+=1
  except (OSError,UnicodeError):continue
print('SRC_REF_FILES_COUNT',count)
print('===EXTERNAL REFERENCES===')
for base in ['/etc/systemd/system','/etc/cron.d','/usr/local/sbin','/root/.pm2','/home/ubuntu/codex-bridge']:
 p=Path(base)
 if not p.is_dir():continue
 matches=[]
 for cur,dirs,files in os.walk(base):
  depth=len(Path(cur).parts)-len(p.parts)
  if depth>3:dirs.clear()
  dirs[:]=[x for x in dirs if x not in ('jobs','node_modules','.git','sessions')]
  for name in files:
   f=Path(cur)/name
   try:
    if f.is_symlink() or f.stat().st_size>800000:continue
    if f.suffix not in ('.service','.timer','.py','.js','.json','.sh','.conf','.md','.yml','.yaml') and f.name!='dump.pm2':continue
    t=f.read_text(errors='replace')
    if old in t or str(vault) in t or str(data) in t:matches.append(str(f))
   except (OSError,UnicodeError):continue
 print('EXTERNAL_REF_FILES',base,len(matches),','.join(matches[:30]))
print('===PM2 DUMP META===')
p=Path('/root/.pm2/dump.pm2')
if p.is_file():
 text=p.read_text(errors='replace')
 print('DUMP_OLD_PATH_REF',text.count(old),'DUMP_VAULT_REF',text.count(str(vault)))
print('===SERVICE BASELINE===')
for name in ['pm2-root','nginx','postgresql@16-main','pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa']:
 r=subprocess.run(['systemctl','is-active',name+'.service'],capture_output=True,text=True,timeout=8)
 print('SERVICE',name,r.stdout.strip())
print('PREFLIGHT_DONE')
